__NUXT_JSONP__("/tw/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"tw",pageTitle:"轉換簽證 | Mentor Language Institute",pageDescription:"感謝您對MLI的支持,此頁面是針對目前在美國沒有F1(學生簽證)，但是想要轉換成F1簽證的人。若是您欲申請，接下來請繼續操作",title:"轉換簽證",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["感謝您對MLI的支持,此頁面是針對目前在美國沒有F1(學生簽證)，但是想要轉換成F1簽證的人。若是您欲申請，接下來請繼續操作:"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-tw.png",link:"\u002Ftw\u002Fadmission"}},applicationSteps:{title:"申請步驟",description:["確切的申請步驟根據您的國家、國籍、課程、簽證需求而不同。我們的人員將根據您的個別情況指示您正確的步驟。"]},needHelp:{title:"需要幫助嗎? 請聯繫我們!",description:["簽證規則及申請步驟依照您的現況有所不同。若是您在申請之前需要詳細說明，歡迎聯繫我們。我們有八個語言的服務。"]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-tw.png",link:"\u002Ftw\u002Fcontact",title:"聯繫我們",lists:[{campus:"\"＜WESTWOOD 院區＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"電話:310⁻887⁻0777"},{campus:"＜HOLLYWOOD 院區＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"電話:310 870 5643\""}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:28.811Z",updatedAt:"2025-05-26T12:06:27.715Z"}}],fetch:{},mutations:void 0});